class Solution:
    def getMinDistSum(self, positions):
        import math
        x = sum(p[0] for p in positions) / len(positions)
        y = sum(p[1] for p in positions) / len(positions)
        def f(px, py):
            return sum(math.hypot(px - a, py - b) for a, b in positions)
        step = 1.0
        cur = f(x, y)
        while step > 1e-7:
            gx = gy = 0.0
            for a, b in positions:
                d = math.hypot(x - a, y - b)
                if d > 1e-12:
                    gx += (x - a) / d
                    gy += (y - b) / d
            nx, ny = x - gx * step, y - gy * step
            val = f(nx, ny)
            if val < cur:
                x, y, cur = nx, ny, val
            else:
                step /= 2
        return cur

