class Solution {
public:
    double getMinDistSum(vector<vector<int>>& positions) {
        int n = positions.size();
        double x = 0, y = 0;
        for (auto& p : positions) { x += p[0]; y += p[1]; }
        x /= n; y /= n;
        auto f = [&](double px, double py) {
            double s = 0;
            for (auto& p : positions) s += hypot(px - p[0], py - p[1]);
            return s;
        };
        double step = 1.0, cur = f(x, y);
        while (step > 1e-7) {
            double gx = 0, gy = 0;
            for (auto& p : positions) {
                double d = hypot(x - p[0], y - p[1]);
                if (d > 1e-12) { gx += (x - p[0]) / d; gy += (y - p[1]) / d; }
            }
            double nx = x - gx * step, ny = y - gy * step;
            double val = f(nx, ny);
            if (val < cur) { x = nx; y = ny; cur = val; }
            else step /= 2;
        }
        return cur;
    }
};

